// Two things arrive at this webhook: a request for the page, and a request
// for one Word file (?file=JS-<slug>.docx). Only a file name of that exact
// shape is fetched, so the query string can never point the fetch anywhere
// else on GitHub.
const q = $input.first().json.query || {};
const file = String(q.file || '');
if (!file) return [{ json: { route: 'index' } }];
if (!/^JS-[a-z0-9-]+\.docx$/.test(file)) return [{ json: { route: 'index' } }];
return [{ json: { route: 'file', file,
  url: `https://github.com/IT-Architect-UK/monorepo/releases/download/jobsheets/${file}` } }];

// The Job sheets page: every service in the catalogue with its Word sheet,
// and the next free job reference. The sheets themselves are built by
// projects/web/itsurgery/jobsheets/build.js in CI and published as assets
// on the rolling "jobsheets" GitHub release; this page only lists and
// serves them, behind the dashboard's sign-in.

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

const safe = (name, path, fallback) => {
  try {
    let v = $(name).first().json;
    for (const k of path) v = v?.[k];
    return v === undefined || v === null ? fallback : v;
  } catch (e) { return fallback; }
};

// The release asset comes back as text (GitHub serves it as octet-stream).
let listing = safe('Sheet list', ['data'], null) ?? safe('Sheet list', [], null);
if (typeof listing === 'string') { try { listing = JSON.parse(listing); } catch (e) { listing = null; } }
const sheets = (listing && Array.isArray(listing.sheets)) ? listing.sheets : null;
const generated = listing && listing.generated ? new Date(listing.generated) : null;

const query = safe('Open the job sheets page', ['query'], {}) || {};

// --- job references ---------------------------------------------------------
// JS-YYYY-NNN, numbered per year. The counter lives in the workflow's static
// data, which a redeploy of this workflow wipes, so the floor below is the
// highest number known to be taken and must be raised by hand whenever the
// counter is lost: it is what stops a duplicate reference.
const TAKEN_FLOOR = { year: 2026, last: 1 };   // JS-2026-001: the first visit
const store = $getWorkflowStaticData('global');
const year = new Date().getFullYear();
if (!store.refs || store.refs.year !== year) {
  store.refs = { year, last: year === TAKEN_FLOOR.year ? TAKEN_FLOOR.last : 0 };
}
if (year === TAKEN_FLOOR.year && store.refs.last < TAKEN_FLOOR.last) store.refs.last = TAKEN_FLOOR.last;
const ref = (n) => `JS-${year}-${String(n).padStart(3, '0')}`;
const nextRef = ref(store.refs.last + 1);

// --- grouping ---------------------------------------------------------------
const groups = [];
(sheets || []).forEach((s) => {
  const aud = s.audience === 'business' ? 'Business' : 'Home';
  const key = `${aud} · ${s.group || 'Other'}`;
  let g = groups.find((x) => x.key === key);
  if (!g) { g = { key, audience: aud, name: s.group || 'Other', items: [] }; groups.push(g); }
  g.items.push(s);
});
const home = groups.filter((g) => g.audience === 'Home');
const business = groups.filter((g) => g.audience === 'Business');

const price = (s) => s.price == null ? '' : s.audience === 'business' ? `£${s.price} + VAT` : `£${s.price} inc. VAT`;
const row = (s) => `<tr>
  <td>${esc(s.name)}${s.status === 'skeleton' ? ' <span class="pill">skeleton</span>' : ''}</td>
  <td class="r">${s.durationMinutes ? s.durationMinutes + ' min' : ''}</td>
  <td class="r">${esc(price(s))}</td>
  <td class="r"><a class="btn" href="/webhook/jobsheets?file=${encodeURIComponent(s.file)}">Download</a></td>
</tr>`;
const section = (g) => `<div class="card"><h2>${esc(g.audience)} · ${esc(g.name)}</h2>
  <table>${g.items.map(row).join('')}</table></div>`;

const full = (sheets || []).filter((s) => s.status === 'full').length;

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600&display=swap" rel="stylesheet">
<title>IT Surgery — Job sheets</title>
<style>
 :root{--brand:#990000;--ink:#333;--strong:#222;--quiet:#5a6068;--line:#dcdfe3;--bg:#f4f5f7}
 *{box-sizing:border-box}
 body{margin:0;background:var(--bg);color:var(--ink);
   font:14px/1.45 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif}
 header{background:#fff;border-bottom:3px solid var(--brand);padding:.85rem 1.25rem;
   display:flex;align-items:center;gap:.9rem;flex-wrap:wrap}
 header img{height:34px}
 .tabs{display:flex;gap:1.1rem;align-items:center;flex-wrap:wrap}
 .tabs a{color:var(--brand);font-weight:600;text-decoration:none;font-size:.9rem;padding-bottom:.2rem}
 .tabs a.on{color:var(--strong);border-bottom:2px solid var(--brand)}
 .out{margin-left:auto;color:var(--quiet);font-size:.85rem;text-decoration:none}
 .out:hover{color:var(--brand)}
 main{padding:1rem 1.25rem;max-width:1100px;margin:0 auto}
 h2{font-family:Poppins,sans-serif;font-weight:600;color:var(--strong);margin:0 0 .75rem;font-size:.95rem}
 .card{background:#fff;border:1px solid var(--line);border-radius:10px;padding:1rem;margin-bottom:1rem}
 table{width:100%;border-collapse:collapse}
 td{padding:.45rem 0;border-bottom:1px solid var(--line);font-size:.9rem;vertical-align:middle}
 tr:last-child td{border-bottom:0}
 td.r{text-align:right;white-space:nowrap;color:var(--quiet);padding-left:.6rem}
 .btn{display:inline-block;background:var(--brand);color:#fff;text-decoration:none;font-weight:600;
   font-size:.8rem;padding:.35rem .7rem;border-radius:6px;border:0;cursor:pointer;font-family:inherit}
 .btn:hover{background:#7a0000}
 .pill{display:inline-block;background:#fff4d6;color:#7a5a00;border:1px solid #e0c471;border-radius:999px;
   font-size:.72rem;padding:.05rem .5rem;margin-left:.4rem;vertical-align:middle}
 .quiet{color:var(--quiet)}
 .ref{display:flex;gap:1rem;align-items:center;flex-wrap:wrap}
 .ref strong{font-family:Poppins,sans-serif;font-size:1.3rem;color:var(--strong)}
 .stale{background:#fff4d6;border:1px solid #e0c471;border-radius:8px;padding:.7rem .9rem;font-size:.85rem;margin-bottom:1rem}
 .ok{background:#e6f4ee;border:1px solid #9fd3b8;border-radius:8px;padding:.7rem .9rem;font-size:.85rem;margin-bottom:1rem}
 @media(max-width:600px){td.r{white-space:normal}.btn{padding:.3rem .5rem}}
 .cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(420px,100%),1fr));gap:0 1rem;align-items:start}
</style></head><body>
<header>
  <img src="https://itsurgery.me/assets/logo.png" alt="IT Surgery">
  <nav class="tabs"><a href="/">Dashboard</a><a href="/monitoring">Monitoring</a><a class="on" href="/webhook/jobsheets">Job sheets</a><a href="/webmin-frame">Webmin</a><a href="/backup">Backup</a><a href="/guide">Guide</a></nav>
  <a class="out" href="/oauth2/sign_out?rd=https%3A%2F%2Flogin.microsoftonline.com%2F0f8703ae-7d51-4894-b66e-75f73e64a903%2Foauth2%2Fv2.0%2Flogout%3Fpost_logout_redirect_uri%3Dhttps%253A%252F%252Fdashboard.itsurgery.me%252Fsigned-out">Sign out</a>
</header>
<main>
  ${query.taken ? `<div class="ok"><strong>${esc(query.taken)}</strong> is yours. Write it in the sheet's Job reference box; the next free number is below.</div>` : ''}
  <div class="card"><h2>Job reference</h2>
    <div class="ref">
      <span class="quiet">Next free</span> <strong>${esc(nextRef)}</strong>
      <form method="POST" action="/webhook/jobsheets-next" style="margin:0"><button class="btn" type="submit">Take next number</button></form>
      <span class="quiet">One per visit, in order. Taken numbers are not reused; the first visit was JS-${TAKEN_FLOOR.year}-${String(TAKEN_FLOOR.last).padStart(3, '0')}.</span>
    </div>
  </div>

  ${sheets ? '' : `<div class="stale"><strong>The sheet list could not be fetched.</strong>
     The Word files are built by the "Job sheets" GitHub Action and published on the repository's
     <code>jobsheets</code> release. If that action has never run, or its last run failed, there is nothing to list yet.</div>`}

  ${sheets ? `<p class="quiet">${sheets.length} services · ${full} written in full, ${sheets.length - full} skeleton${
    generated ? ` · built ${esc(generated.toLocaleString('en-GB', { timeZone: 'Europe/London', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }))}` : ''}.
    A <span class="pill" style="margin:0">skeleton</span> sheet has the real header and the generic steps; its service-specific content has not been written yet.
    Templates live in <code>projects/web/itsurgery/jobsheets/</code>.</p>` : ''}

  <div class="cols">
    <div>${home.map(section).join('')}</div>
    <div>${business.map(section).join('')}</div>
  </div>
</main></body></html>`;

return [{ json: { html } }];

// "Take next number": hand out the next job reference and remember it.
// Same counter, same floor rule as the page (see "Build the page"): the
// floor is the highest reference known to be taken and survives a redeploy
// when the static data does not.
const TAKEN_FLOOR = { year: 2026, last: 1 };
const store = $getWorkflowStaticData('global');
const year = new Date().getFullYear();
if (!store.refs || store.refs.year !== year) {
  store.refs = { year, last: year === TAKEN_FLOOR.year ? TAKEN_FLOOR.last : 0 };
}
if (year === TAKEN_FLOOR.year && store.refs.last < TAKEN_FLOOR.last) store.refs.last = TAKEN_FLOOR.last;
store.refs.last += 1;
const taken = `JS-${year}-${String(store.refs.last).padStart(3, '0')}`;
return [{ json: { taken, url: `/webhook/jobsheets?taken=${encodeURIComponent(taken)}` } }];
